# Diagnostic snapshot only. Exact PIDs, type names/counts only; no object names, paths or remote handle closure.
[CmdletBinding()]
param([Parameter(Mandatory=$true)][ValidateCount(1,8)][int[]]$OwnedPids)
$ErrorActionPreference='Stop'
if(-not ('AtmosHandleTypes.Probe' -as [type])){Add-Type -TypeDefinition @'
using System;using System.Collections.Generic;using System.Runtime.InteropServices;
namespace AtmosHandleTypes {
 public sealed class Row {public int ProcessId;public int SnapshotHandleCount;public Dictionary<string,int> Types;public string[] Errors;}
 public static class Probe {
  [StructLayout(LayoutKind.Sequential)]struct Entry{public IntPtr Object;public UIntPtr Process;public UIntPtr Handle;public uint Access;public ushort Trace;public ushort Type;public uint Attributes;public uint Reserved;}
  [StructLayout(LayoutKind.Sequential)]struct Unicode{public ushort Length;public ushort Maximum;public IntPtr Buffer;}
  [DllImport("ntdll.dll")]static extern int NtQuerySystemInformation(int info,IntPtr data,uint bytes,out uint needed);
  [DllImport("ntdll.dll")]static extern int NtQueryObject(IntPtr handle,int info,IntPtr data,uint bytes,out uint needed);
  [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
  [DllImport("kernel32.dll")]static extern IntPtr GetCurrentProcess();
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool DuplicateHandle(IntPtr source,IntPtr handle,IntPtr destination,out IntPtr duplicate,uint access,bool inherit,uint options);
  [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
  static string TypeName(IntPtr process,UIntPtr value){IntPtr duplicate;if(!DuplicateHandle(process,new IntPtr(unchecked((long)value.ToUInt64())),GetCurrentProcess(),out duplicate,0,false,2))return null;try{uint bytes=1024;for(int pass=0;pass<2;pass++){IntPtr data=Marshal.AllocHGlobal((int)bytes);try{uint needed;int status=NtQueryObject(duplicate,2,data,bytes,out needed);if(status==0){Unicode text=(Unicode)Marshal.PtrToStructure(data,typeof(Unicode));long start=data.ToInt64(),ptr=text.Buffer.ToInt64();if(text.Length%2!=0||text.Length>bytes||ptr<start||ptr+text.Length>start+bytes)return null;return Marshal.PtrToStringUni(text.Buffer,text.Length/2);}if(needed>bytes&&needed<=65536){bytes=needed;continue;}return null;}finally{Marshal.FreeHGlobal(data);}}return null;}finally{CloseHandle(duplicate);}}
  public static Row[] Read(int[] pids){if(IntPtr.Size!=8)throw new InvalidOperationException("64-bit Windows process required");var requested=new HashSet<int>(pids);foreach(int pid in requested)if(pid<=0)throw new ArgumentException("Positive explicit PIDs required");IntPtr buffer=IntPtr.Zero;uint bytes=4*1024*1024;try{int status=-1;uint needed=0;for(int retry=0;retry<7;retry++){if(buffer!=IntPtr.Zero)Marshal.FreeHGlobal(buffer);buffer=Marshal.AllocHGlobal((int)bytes);status=NtQuerySystemInformation(64,buffer,bytes,out needed);if(status==0)break;if(status!=unchecked((int)0xC0000004))throw new InvalidOperationException("NtQuerySystemInformation status 0x"+unchecked((uint)status).ToString("X8"));bytes=Math.Max(bytes*2,needed+65536);if(bytes>256*1024*1024)throw new InvalidOperationException("Handle snapshot exceeds bound");}if(status!=0)throw new InvalidOperationException("Handle snapshot did not stabilize");ulong count=unchecked((ulong)Marshal.ReadInt64(buffer));int size=Marshal.SizeOf(typeof(Entry));if(count>(bytes-16)/(ulong)size)throw new InvalidOperationException("Invalid handle snapshot size");var entries=new Dictionary<int,List<Entry>>();foreach(int pid in requested)entries[pid]=new List<Entry>();for(ulong i=0;i<count;i++){Entry e=(Entry)Marshal.PtrToStructure(IntPtr.Add(buffer,16+checked((int)i*size)),typeof(Entry));ulong process=e.Process.ToUInt64();if(process<=int.MaxValue&&requested.Contains((int)process))entries[(int)process].Add(e);}var output=new List<Row>();var typeNames=new Dictionary<ushort,string>();foreach(int pid in requested){var list=entries[pid];var counts=new Dictionary<ushort,int>();foreach(var e in list){if(!counts.ContainsKey(e.Type))counts[e.Type]=0;counts[e.Type]++;}IntPtr process=OpenProcess(0x0040,false,pid);var errors=new List<string>();if(process==IntPtr.Zero)errors.Add("OpenProcess(PROCESS_DUP_HANDLE):"+Marshal.GetLastWin32Error());else{try{foreach(var e in list){if(typeNames.ContainsKey(e.Type))continue;string name=TypeName(process,e.Handle);if(name!=null)typeNames[e.Type]=name;}}finally{CloseHandle(process);}}var types=new Dictionary<string,int>();foreach(var pair in counts){string key=typeNames.ContainsKey(pair.Key)?typeNames[pair.Key]:"UnresolvedTypeIndex-"+pair.Key;types[key]=pair.Value;}output.Add(new Row{ProcessId=pid,SnapshotHandleCount=list.Count,Types=types,Errors=errors.ToArray()});}return output.ToArray();}finally{if(buffer!=IntPtr.Zero)Marshal.FreeHGlobal(buffer);}}
 }
}
'@ -ErrorAction Stop|Out-Null}
[pscustomobject]@{schemaVersion=1;capturedAtUtc=[DateTime]::UtcNow.ToString('o');source='Read-only NT handle snapshot; local DuplicateHandle with DUPLICATE_SAME_ACCESS and ObjectTypeInformation only';processes=@([AtmosHandleTypes.Probe]::Read($OwnedPids));limitations=@('Uses Windows extended handle information diagnostic layout; unsupported or access-denied systems return errors.','Only local duplicate handles are closed; original target handles are never closed.','Names of handle objects, commands, files, registry keys and private paths are never queried or printed.','One type/count snapshot is not a causal leak diagnosis.')}|ConvertTo-Json -Depth 6 -Compress
